import java.util.Objects;

public final class QuickSortDemo {
    private static final int[] SAMPLE_VALUES = {10, 7, 8, 9, 1, 5};

    private QuickSortDemo() {
    }

    public static void main(String[] args) {
        int[] values = SAMPLE_VALUES.clone();

        QuickSort.sort(values);

        System.out.print(formatValues(values));
    }

    static String formatValues(int[] values) {
        Objects.requireNonNull(values, "values");

        StringBuilder formattedValues = new StringBuilder();
        for (int value : values) {
            formattedValues.append(value).append(' ');
        }

        return formattedValues.toString();
    }
}

import java.util.Objects;

public final class QuickSort {
    private QuickSort() {
    }

    public static void sort(int[] values) {
        Objects.requireNonNull(values, "values");

        if (values.length < 2) {
            return;
        }

        quickSort(values, 0, values.length - 1);
    }

    private static void quickSort(int[] values, int startIndex, int endIndex) {
        while (startIndex < endIndex) {
            PartitionBounds partitionBounds = partition(values, startIndex, endIndex);

            int leftPartitionSize = partitionBounds.leftPartitionSize(startIndex);
            int rightPartitionSize = partitionBounds.rightPartitionSize(endIndex);

            // Recurse into the smaller partition first to limit stack growth.
            if (leftPartitionSize < rightPartitionSize) {
                quickSort(values, startIndex, partitionBounds.lessThanEndIndex);
                startIndex = partitionBounds.greaterThanStartIndex;
            } else {
                quickSort(values, partitionBounds.greaterThanStartIndex, endIndex);
                endIndex = partitionBounds.lessThanEndIndex;
            }
        }
    }

    private static PartitionBounds partition(int[] values, int startIndex, int endIndex) {
        int pivot = values[choosePivotIndex(startIndex, endIndex)];
        int nextLowerValueIndex = startIndex;
        int currentIndex = startIndex;
        int nextHigherValueIndex = endIndex;

        while (currentIndex <= nextHigherValueIndex) {
            if (values[currentIndex] < pivot) {
                swap(values, nextLowerValueIndex, currentIndex);
                nextLowerValueIndex++;
                currentIndex++;
            } else if (values[currentIndex] > pivot) {
                swap(values, currentIndex, nextHigherValueIndex);
                nextHigherValueIndex--;
            } else {
                currentIndex++;
            }
        }

        return new PartitionBounds(nextLowerValueIndex - 1, nextHigherValueIndex + 1);
    }

    private static int choosePivotIndex(int startIndex, int endIndex) {
        return startIndex + (endIndex - startIndex) / 2;
    }

    private static void swap(int[] values, int firstIndex, int secondIndex) {
        if (firstIndex == secondIndex) {
            return;
        }

        int temporaryValue = values[firstIndex];
        values[firstIndex] = values[secondIndex];
        values[secondIndex] = temporaryValue;
    }

    public static void main(String[] args) {
        QuickSortDemo.main(args);
    }

    private static final class PartitionBounds {
        private final int lessThanEndIndex;
        private final int greaterThanStartIndex;

        private PartitionBounds(int lessThanEndIndex, int greaterThanStartIndex) {
            this.lessThanEndIndex = lessThanEndIndex;
            this.greaterThanStartIndex = greaterThanStartIndex;
        }

        private int leftPartitionSize(int startIndex) {
            return Math.max(0, lessThanEndIndex - startIndex + 1);
        }

        private int rightPartitionSize(int endIndex) {
            return Math.max(0, endIndex - greaterThanStartIndex + 1);
        }
    }
}

import java.util.Arrays;

public final class QuickSortTest {
    private QuickSortTest() {
    }

    public static void main(String[] args) {
        for (SortScenario scenario : sortScenarios()) {
            assertSorted(scenario);
        }

        assertNullRejected();
        assertFormattedValues();
    }

    private static SortScenario[] sortScenarios() {
        return new SortScenario[] {
            new SortScenario(
                    "sample values",
                    new int[] {10, 7, 8, 9, 1, 5},
                    new int[] {1, 5, 7, 8, 9, 10}),
            new SortScenario("empty array", new int[] {}, new int[] {}),
            new SortScenario("single value", new int[] {4}, new int[] {4}),
            new SortScenario(
                    "duplicate values",
                    new int[] {3, 1, 3, 2, 1},
                    new int[] {1, 1, 2, 3, 3}),
            new SortScenario(
                    "all equal values",
                    new int[] {7, 7, 7, 7},
                    new int[] {7, 7, 7, 7}),
            new SortScenario(
                    "many duplicate values",
                    new int[] {4, 2, 4, 4, 1, 2, 4},
                    new int[] {1, 2, 2, 4, 4, 4, 4}),
            new SortScenario(
                    "negative values",
                    new int[] {0, -4, 8, -1},
                    new int[] {-4, -1, 0, 8}),
            new SortScenario(
                    "already sorted values",
                    new int[] {1, 2, 3, 4, 5},
                    new int[] {1, 2, 3, 4, 5}),
            new SortScenario(
                    "reverse sorted values",
                    new int[] {5, 4, 3, 2, 1},
                    new int[] {1, 2, 3, 4, 5})
        };
    }

    private static void assertSorted(SortScenario scenario) {
        int[] values = scenario.inputValues.clone();
        QuickSort.sort(values);

        if (!Arrays.equals(values, scenario.expectedValues)) {
            throw new AssertionError(
                    scenario.name
                            + ": expected "
                            + Arrays.toString(scenario.expectedValues)
                            + " but got "
                            + Arrays.toString(values));
        }
    }

    private static void assertNullRejected() {
        try {
            QuickSort.sort(null);
            throw new AssertionError("null values should be rejected");
        } catch (NullPointerException expected) {
            // Expected by the public sorting contract.
        }
    }

    private static void assertFormattedValues() {
        String formattedValues = QuickSortDemo.formatValues(new int[] {1, 5, 7});

        if (!"1 5 7 ".equals(formattedValues)) {
            throw new AssertionError("formatted values should preserve the legacy console output");
        }
    }

    private static final class SortScenario {
        private final String name;
        private final int[] inputValues;
        private final int[] expectedValues;

        private SortScenario(String name, int[] inputValues, int[] expectedValues) {
            this.name = name;
            this.inputValues = inputValues;
            this.expectedValues = expectedValues;
        }
    }
}
